/**
 * Empirically derived scale factor for stable hashed alpha thresholds.
 * Used to control the granularity of the hash pattern in volumetric rendering.
 * @constant {number}
 * @category TSL
 * @private
 */
export const ALPHA_HASH_SCALE: 0.05;
/**
 * Generate a spatially-stable hashed alpha threshold for volumetric rendering.
 *
 * **Algorithm**
 * - Computes screen-space derivative to determine sampling density
 * - Generates hash value based on world position scaled to pixel grid
 * - Applies smooth remapping to avoid banding artifacts
 * - Returns threshold in [0..1] for alpha testing
 *
 * **Use Cases**
 * - Volumetric smoke/fog with stable dithering patterns
 * - Screen-space depth-aware alpha blending
 * - Avoiding temporal aliasing in volume rendering
 *
 * ```js
 * import { getAlphaHashThreshold } from '@three-blocks/core';
 * import { positionWorld } from 'three/tsl';
 *
 * // In fragment shader
 * const threshold = getAlphaHashThreshold(positionWorld);
 * const alpha = smoothstep(threshold, threshold.add(0.01), density);
 * outputNode = vec4(color.rgb, alpha);
 * ```
 *
 * @function getAlphaHashThreshold
 * @private
 * @category TSL
 * @tsl
 * @param {Node.<vec3>} position World-space or view-space position for hash calculation.
 * @returns {Node.<float>} Alpha threshold value in [0..1].
 */
export const getAlphaHashThreshold: any;
export default getAlphaHashThreshold;
